-- Граматика A2: 22 тем
do $$
begin
  if not exists (select 1 from public.grammar_topics where id = '0c68352a-803a-5410-a59b-91f2c1ddc49f') then raise exception 'Немає теми граматики A2 KOND'; end if;
  if exists (select 1 from public.grammar_rules where topic_id = '0c68352a-803a-5410-a59b-91f2c1ddc49f') then return; end if;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '0c68352a-803a-5410-a59b-91f2c1ddc49f';
  update public.grammar_topics set title_ua = 'Умовний спосіб: kondicional I', title_hr = 'Kondicional I.', description = 'Kondicional I для ввічливих прохань (htio bih, biste li mogli), бажань (volio bih) і мети (da bih): форми bih, bi, bismo, biste, bi + дієслівна форма на -o / -la; місце bih у реченні; типові помилки українців.', status = 'PUBLISHED'
   where id = '0c68352a-803a-5410-a59b-91f2c1ddc49f';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c43c373f-c952-5a04-88fc-a17c1dfa9384', '0c68352a-803a-5410-a59b-91f2c1ddc49f', 'Як утворюється kondicional', 'Kondicional I = коротка форма bih, bi, bi, bismo, biste, bi + та сама форма на -o / -la / -lo / -li, що в perfekt: ja bih htio / htjela, ti bi došao, mi bismo išli, vi biste platili. В українській це «б» + минулий час: «я б хотів». Bih змінюється за особою — не кажіть «ja bi htio».', 'ja bih htio · ti bi htio · on bi htio · mi bismo htjeli · vi biste htjeli · oni bi htjeli', '[{"hr": "Htio bih sobu s pogledom na more.", "ua": "Я хотів би номер з видом на море."}, {"hr": "Bismo li mogli platiti karticom?", "ua": "Чи могли б ми заплатити карткою?"}, {"hr": "Darja bi radije išla vlakom.", "ua": "Дар’я радше поїхала б потягом."}, {"hr": "Što biste vi preporučili?", "ua": "Що б ви порадили?"}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('83df8ec4-c84f-5faa-9845-1dfcb9fad424', '0c68352a-803a-5410-a59b-91f2c1ddc49f', 'Ввічливе прохання', 'Kondicional робить прохання м’якшим: замість Hoću kavu (хочу каву) кажемо Htio bih kavu / Htjela bih kavu. Питання з Biste li mogli…? — найввічливіше: Biste li mogli ponoviti? Зверніть увагу: bih / biste стоять на другому місці, після першого слова: Molim Vas, mogli biste li… — ні; правильно: Biste li mi, molim Vas, pomogli?', 'Htio / Htjela bih… · Biste li mogli…? · Bi li bilo moguće…?', '[{"hr": "Htjela bih rezervirati stol za četvero.", "ua": "Я хотіла б забронювати столик на чотирьох."}, {"hr": "Biste li mogli ponoviti, molim Vas?", "ua": "Чи не могли б ви повторити, будь ласка?"}, {"hr": "Bi li bilo moguće ranije se prijaviti?", "ua": "Чи можна було б заселитися раніше?"}, {"hr": "Trebao bih Vašu pomoć.", "ua": "Мені була б потрібна ваша допомога."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('86116dae-ffa7-5c84-94ea-6e10eef67a11', '0c68352a-803a-5410-a59b-91f2c1ddc49f', 'Бажання й мета: volio bih, da bih', 'Volio bih / Voljela bih — «я б дуже хотів», про мрії й бажання: Volio bih živjeti uz more. Мета — da + kondicional: Učim hrvatski da bih našla bolji posao (щоб знайти). Типова помилка українця — «da ja nađem» замість da bih našla; якщо мета стосується іншої людини, кажемо da + теперішній час: Govorim polako da me razumiješ.', 'Volio / Voljela bih… · da bih / da bismo + -o / -la', '[{"hr": "Voljela bih jednog dana otvoriti kafić.", "ua": "Я б хотіла колись відкрити кав’ярню."}, {"hr": "Upisao sam tečaj da bih lakše našao posao.", "ua": "Я записався на курс, щоб легше знайти роботу."}, {"hr": "Štedimo da bismo kupili stan.", "ua": "Ми заощаджуємо, щоб купити квартиру."}, {"hr": "Govori polako da te razumijem.", "ua": "Говори повільно, щоб я тебе зрозумів."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('36d45271-3f62-52c1-9648-c84cb726989b', '0c68352a-803a-5410-a59b-91f2c1ddc49f', 'Якби…: ako і kad з kondicionalom', 'Нереальна умова: Da imam vremena, išao bih na more (якби мав час, поїхав би). У розмові також: Kad bih imao novca, kupio bih auto. Після da в умові — теперішній час (Da imam…, Da znam…), а в головній частині — kondicional. Не плутайте з реальною умовою ako + теперішній: Ako imam vremena, idem na more.', 'Da imam…, išao bih… · Kad bih imao…, kupio bih…', '[{"hr": "Da imam više vremena, učila bih talijanski.", "ua": "Якби я мала більше часу, вчила б італійську."}, {"hr": "Kad bih dobio taj posao, preselio bih se u Split.", "ua": "Якби я отримав ту роботу, переїхав би до Спліта."}, {"hr": "Da znam, rekla bih ti.", "ua": "Якби я знала, сказала б тобі."}, {"hr": "Da je ljeto, kupali bismo se.", "ua": "Якби було літо, ми б купалися."}]'::jsonb, 4)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '0c68352a-803a-5410-a59b-91f2c1ddc49f', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '0c68352a-803a-5410-a59b-91f2c1ddc49f' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
do $$
begin
  if not exists (select 1 from public.grammar_topics where id = '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc') then raise exception 'Немає теми граматики A2 ZAV'; end if;
  if exists (select 1 from public.grammar_rules where topic_id = '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc') then return; end if;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc';
  update public.grammar_topics set title_ua = 'Підрядні речення: ako, kad, dok, čim, da, što', title_hr = 'Zavisne rečenice', description = 'Складні речення з ako (якщо), kad (коли), dok (поки), čim (щойно), nakon što (після того як), da (що) і što (що, тому що): порядок слів, час у підрядній частині, кома.', status = 'PUBLISHED'
   where id = '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('e8a50f0f-38cf-5da8-a9f0-36ad4338bbf0', '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc', 'Ako — реальна умова', 'Ako + теперішній час — умова, яка може виконатися: Ako pada kiša, ostajemo kod kuće. Про майбутнє в підрядній частині теж теперішній час або futur: Ako stigneš ranije, nazovi me. Українці часто ставлять тут «budem» — на A2 краще просто теперішній час доконаного дієслова: Ako dođeš, …', 'Ako + теперішній, (головне речення)', '[{"hr": "Ako je more mirno, idemo brodicom.", "ua": "Якщо море спокійне, поїдемо човном."}, {"hr": "Ako stigneš ranije, nazovi me.", "ua": "Якщо приїдеш раніше, подзвони мені."}, {"hr": "Ako ne platite predujam, rezervacija se otkazuje.", "ua": "Якщо ви не внесете передоплату, бронювання скасовується."}, {"hr": "Što ćemo raditi ako trajekt kasni?", "ua": "Що ми робитимемо, якщо пором запізниться?"}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('4309aa06-3d60-5538-b068-46b63205432f', '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc', 'Kad, dok, čim, nakon što — час', 'Kad — коли; dok — поки, тоді як (дві дії одночасно): Dok ja kuham, ti postavi stol. Čim — щойно: Čim stignem, javit ću ti se. Nakon što — після того як: Nakon što sam završio školu, preselio sam se. Prije nego što — перед тим як. Підрядна частина може стояти першою — тоді після неї кома.', 'kad · dok · čim · nakon što · prije nego što', '[{"hr": "Kad sam bila mala, živjeli smo na selu.", "ua": "Коли я була маленька, ми жили в селі."}, {"hr": "Dok je baka kuhala, djed je čitao novine.", "ua": "Поки бабуся готувала, дідусь читав газету."}, {"hr": "Čim je zazvonilo, djeca su istrčala van.", "ua": "Щойно задзвонило, діти вибігли надвір."}, {"hr": "Nakon što smo se preselili, sve se promijenilo.", "ua": "Після того як ми переїхали, усе змінилося."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('679fcc7d-1a2a-5fac-9021-a883ce62b24f', '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc', 'Da і što — «що»', 'Da вводить зміст думки чи слів: Mislim da je to dobra ideja. Rekla je da kasni. Što — «що» як займенник або «тому що, що» після почуттів: Drago mi je što si došao (радий, що ти прийшов). Типова помилка — «Mislim što…»: після misliti, reći, znati, čuti — завжди da.', 'Mislim da… · Rekao je da… · Drago mi je što…', '[{"hr": "Mislim da je film predugačak.", "ua": "Я думаю, що фільм задовгий."}, {"hr": "Čula sam da se otvara nova knjižnica.", "ua": "Я чула, що відкривається нова бібліотека."}, {"hr": "Drago mi je što ste nas posjetili.", "ua": "Мені приємно, що ви нас відвідали."}, {"hr": "Žao mi je što nisam mogla doći.", "ua": "Мені шкода, що я не змогла прийти."}]'::jsonb, 3)
on conflict (id) do nothing;
