where not exists (select 1 from public.content_reviews where entity_id = '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
