  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '0b2de584-05a6-5570-a129-366fcb94766d';
  update public.grammar_topics set title_ua = 'Вид дієслова: недоконаний і доконаний', title_hr = 'Glagolski vid', description = 'Пари недоконаного й доконаного виду (upisivati / upisati, kupovati / kupiti, dolaziti / doći): процес і результат, повторення й одна дія, вид у минулому, майбутньому й наказовому способі.', status = 'PUBLISHED'
   where id = '0b2de584-05a6-5570-a129-366fcb94766d';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('368bd665-5c2d-5fb8-89cb-38ad1fde1814', '0b2de584-05a6-5570-a129-366fcb94766d', 'Процес чи результат', 'Як в українській, більшість дієслів мають пару: недоконаний вид — процес або повторення (upisivati — записувати, записуватися), доконаний — одна завершена дія з результатом (upisati — записати, записатися). Пари утворюються префіксом (pisati → napisati), суфіксом (upisati → upisivati) або різними словами (dolaziti → doći).', 'pisati / napisati · upisivati / upisati · kupovati / kupiti · dolaziti / doći', '[{"hr": "Svake godine upisujem novi tečaj.", "ua": "Щороку я записуюся на новий курс."}, {"hr": "Ove godine sam upisala fakultet.", "ua": "Цього року я вступила до університету."}, {"hr": "Pišem zadaću već sat vremena.", "ua": "Я пишу домашнє завдання вже годину."}, {"hr": "Napisala sam zadaću i idem van.", "ua": "Я написала домашнє завдання й іду надвір."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c985c5e0-bbdc-5883-9f10-0cd09c23d6f2', '0b2de584-05a6-5570-a129-366fcb94766d', 'Вид у теперішньому часі', 'Доконане дієслово в теперішньому часі не означає «зараз»: воно вживається після da, ako, kad, čim і в майбутньому. Kupim kruh — так не кажуть про «зараз»; кажуть Kupujem kruh (купую). Але: Moram kupiti kruh. Ako kupiš kruh, … Типова помилка українців — доконане дієслово для дії, що відбувається зараз.', 'Sad pišem e-mail. · Moram napisati e-mail. · Čim napišem e-mail, …', '[{"hr": "Trebam predati zahtjev do petka.", "ua": "Мені треба подати заяву до п’ятниці."}, {"hr": "Upravo predajem zahtjev na šalteru.", "ua": "Я якраз подаю заяву у віконці."}, {"hr": "Čim dobijem potvrdu, javit ću Vam.", "ua": "Щойно отримаю довідку, повідомлю вам."}, {"hr": "Ako položiš ispit, slavimo!", "ua": "Якщо складеш іспит, святкуємо!"}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('30564922-2623-5ff4-b189-0ba8e9f44c84', '0b2de584-05a6-5570-a129-366fcb94766d', 'Вид у наказовому способі й майбутньому', 'У проханні про одну конкретну дію — доконаний вид: Pošaljite mi ponudu. Pričekajte trenutak. Недоконаний — про постійну дію або заборону: Šaljite izvještaje svaki petak. Ne pušite ovdje. У futur: Napisat ću ti sutra (одна дія) — Pisat ću ti često (повторення).', 'Pošaljite! — Šaljite svaki tjedan! · Napisat ću. — Pisat ću.', '[{"hr": "Pošaljite mi, molim Vas, izvještaj do podne.", "ua": "Надішліть мені, будь ласка, звіт до обіду."}, {"hr": "Šaljite mi izvještaje svakog petka.", "ua": "Надсилайте мені звіти щоп’ятниці."}, {"hr": "Nazvat ću te kad stignem.", "ua": "Я подзвоню тобі, коли приїду."}, {"hr": "Zvat ću te svaki dan.", "ua": "Я дзвонитиму тобі щодня."}]'::jsonb, 3)
on conflict (id) do nothing;
