where not exists (select 1 from public.content_reviews where entity_id = '0b2de584-05a6-5570-a129-366fcb94766d' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
