  if not exists (select 1 from public.grammar_topics where id = '2d4021eb-fd3e-5388-a44b-3f541c5990f8') then raise exception 'Немає теми граматики A2 ZAM'; end if;
  if exists (select 1 from public.grammar_rules where topic_id = '2d4021eb-fd3e-5388-a44b-3f541c5990f8') then return; end if;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '2d4021eb-fd3e-5388-a44b-3f541c5990f8';
  update public.grammar_topics set title_ua = 'Займенники: повні й короткі форми', title_hr = 'Zamjenice: naglašeni i nenaglašeni oblici', description = 'Повні (mene, tebe, njega, nju…) і короткі (me, te, ga, je, mi, ti, mu, joj…) форми особових займенників у родовому, давальному й знахідному відмінках: коли яку вживати, де стоїть коротка форма.', status = 'PUBLISHED'
   where id = '2d4021eb-fd3e-5388-a44b-3f541c5990f8';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('e9986b38-a33f-5799-bc94-e0e58c6df25e', '2d4021eb-fd3e-5388-a44b-3f541c5990f8', 'Знахідний: mene / me, njega / ga, nju / je', 'Коротка форма — звичайна: Vidim ga. Zovem te sutra. Повна — для наголосу, протиставлення й після прийменника: Vidim njega, a ne nju. Čekam na tebe. Za mene je to važno. Жіночий рід: nju / je (і ju перед je: Vidio ju je). Не кажіть «Vidim njega» без наголосу — це звучить як «саме його».', 'me · te · ga · je (ju) · nas · vas · ih — mene · tebe · njega · nju · nas · vas · njih', '[{"hr": "Poznaješ li Ivu? — Poznajem ga od škole.", "ua": "Ти знаєш Іву? — Знаю його зі школи."}, {"hr": "To je za tebe, ne za mene.", "ua": "Це для тебе, а не для мене."}, {"hr": "Darja nas je pozvala na rođendan.", "ua": "Дар’я запросила нас на день народження."}, {"hr": "Čekam vas ispred škole.", "ua": "Чекаю вас перед школою."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('e82e095e-b42b-5b6d-8874-8300da0670bd', '2d4021eb-fd3e-5388-a44b-3f541c5990f8', 'Давальний: meni / mi, njemu / mu, njoj / joj', 'Короткі форми давального: mi, ti, mu, joj, nam, vam, im — Daj mi. Reci mu. Sviđa mi se. Повні — meni, tebi, njemu, njoj, nama, vama, njima — для наголосу й після prema, k: Meni se sviđa, a tebi? Idem k njoj. В українській «йому / їй» звучить однаково — у хорватській коротка форма mu / joj значно частіша.', 'mi · ti · mu · joj · nam · vam · im — meni · tebi · njemu · njoj · nama · vama · njima', '[{"hr": "Reci joj da sam stigla.", "ua": "Скажи їй, що я приїхала."}, {"hr": "Meni je ovaj film dosadan, a tebi?", "ua": "Мені цей фільм нудний, а тобі?"}, {"hr": "Pomozi mu s torbom, molim te.", "ua": "Допоможи йому із сумкою, будь ласка."}, {"hr": "Šef nam je dao slobodan dan.", "ua": "Шеф дав нам вільний день."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c6260400-9609-58d7-9f45-8ee8948207f7', '2d4021eb-fd3e-5388-a44b-3f541c5990f8', 'Родовий і прийменники', 'Родовий займенників збігається зі знахідним: mene / me, tebe / te, njega / ga, nje / je, nas, vas, njih / ih. Після прийменників (od, do, kod, bez, osim) — лише повна форма: kod mene, bez njega, od nje. Типова помилка — «kod me» чи «od ga»: після прийменника коротких форм не буває.', 'kod mene · bez tebe · od njega · do nje · osim nas · kod njih', '[{"hr": "Ključ je kod mene.", "ua": "Ключ у мене."}, {"hr": "Bez tebe ne idem.", "ua": "Без тебе я не піду."}, {"hr": "Dobila sam poruku od njega.", "ua": "Я отримала від нього повідомлення."}, {"hr": "Svi su došli osim njih.", "ua": "Усі прийшли, крім них."}]'::jsonb, 3)
on conflict (id) do nothing;
