         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '926638d7-1396-512e-8a05-065c4464b85a';
  update public.grammar_topics set title_ua = 'Порівняльні конструкції', title_hr = 'Poredbene konstrukcije', description = 'Порівняння: bolji od, više od, manje nego, isti kao, kao i, sve više, što prije to bolje, najviše; прислівники bolje, gore, više, manje.', status = 'PUBLISHED'
   where id = '926638d7-1396-512e-8a05-065c4464b85a';
