insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('42348cc6-2c24-52fe-aa83-afc81930bb95', '926638d7-1396-512e-8a05-065c4464b85a', 'Od і nego', 'Після вищого ступеня — od + родовий: Split je veći od Zadra. Ova knjiga je zanimljivija od filma. Nego — коли порівнюємо не іменники, а дії, прислівники чи цілі частини: Radije čitam nego gledam televiziju. Bolje je sada nego nikad. Типова помилка — «veći kao Zadar»: kao лише для рівності.', 'veći od + G · više nego · radije … nego …', '[{"hr": "Film je bio bolji od knjige.", "ua": "Фільм був кращий за книжку."}, {"hr": "Više volim radio nego televiziju.", "ua": "Я більше люблю радіо, ніж телевізор."}, {"hr": "Danas je toplije nego jučer.", "ua": "Сьогодні тепліше, ніж учора."}, {"hr": "Ova serija je napetija od prve.", "ua": "Цей серіал напруженіший за перший."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('d487cb68-6014-581a-b3aa-519ca1989ce0', '926638d7-1396-512e-8a05-065c4464b85a', 'Isti kao, kao i, jednako', 'Рівність: isti kao (такий самий, як), kao i (як і), jednako + прикметник + kao: Moj stav je isti kao tvoj. I ja mislim kao i ti. Ova emisija je jednako dobra kao prošla. Заперечення: nije tako dobar kao… (не такий добрий, як…).', 'isti kao · kao i · jednako … kao · nije tako … kao', '[{"hr": "Imam isti telefon kao ti.", "ua": "У мене такий самий телефон, як у тебе."}, {"hr": "Nastavak nije tako dobar kao prvi dio.", "ua": "Продовження не таке добре, як перша частина."}, {"hr": "I ja volim jazz, kao i moj otac.", "ua": "Я теж люблю джаз, як і мій батько."}, {"hr": "Cijene su jednako visoke kao lani.", "ua": "Ціни такі самі високі, як торік."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('b8ab3849-1406-5a21-8a41-df1d39e3aa33', '926638d7-1396-512e-8a05-065c4464b85a', 'Sve više, što prije to bolje', 'Sve + вищий ступінь — «дедалі»: sve više ljudi (дедалі більше людей), sve skuplje (дедалі дорожче). Što + вищий ступінь — «якнайшвидше»: što prije, što više. Što…, to… — «чим…, тим…»: Što više čitaš, to bolje pišeš.', 'sve više · što prije · što …, to …', '[{"hr": "Sve više ljudi čita vijesti na mobitelu.", "ua": "Дедалі більше людей читає новини на мобільному."}, {"hr": "Javite mi se što prije.", "ua": "Озвіться до мене якнайшвидше."}, {"hr": "Što više slušaš, to bolje razumiješ.", "ua": "Що більше слухаєш, то краще розумієш."}, {"hr": "Karte su sve skuplje.", "ua": "Квитки дедалі дорожчі."}]'::jsonb, 3)
on conflict (id) do nothing;
