insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c9b853ad-5950-510d-9f92-be4b64644119', 'b7103d09-8e69-53f7-8f17-a90c771fa1a2', 'Родовий множини', 'Чоловічий і середній рід — -a (часто з рухомим a): dokument → dokumenata, mjesec → mjeseci (виняток), prozor → prozora. Жіночий на -a — -a: usluga → usluga, potvrda → potvrda; на приголосний — -i: stvar → stvari. Після puno, malo, koliko, nekoliko і чисел від 5 — родовий множини: pet dokumenata, puno ljudi.', 'puno dokumenata · nekoliko usluga · pet stvari · koliko ljudi?', '[{"hr": "Trebam nekoliko dokumenata.", "ua": "Мені потрібно кілька документів."}, {"hr": "Na šalteru je bilo puno ljudi.", "ua": "Біля віконця було багато людей."}, {"hr": "Koliko potvrda moram donijeti?", "ua": "Скільки довідок я маю принести?"}, {"hr": "Pet godina radim u Hrvatskoj.", "ua": "П’ять років я працюю в Хорватії."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('ad9ed1a5-1d77-52df-aefa-ab54c30669e0', 'b7103d09-8e69-53f7-8f17-a90c771fa1a2', 'Zbog, umjesto, tijekom, osim, nakon', 'Ці прийменники завжди з родовим: zbog kiše (через дощ), umjesto mene (замість мене), tijekom ljeta (протягом літа), osim nedjelje (крім неділі), nakon posla (після роботи), prije ručka (перед обідом). В українській «через» буває і з знахідним — у хорватській причина лише zbog + G.', 'zbog + G · umjesto + G · tijekom + G · osim + G · nakon / prije + G', '[{"hr": "Ured je zatvoren zbog praznika.", "ua": "Офіс зачинено через свято."}, {"hr": "Može li doći netko umjesto mene?", "ua": "Чи може прийти хтось замість мене?"}, {"hr": "Tijekom ljeta radimo do dva.", "ua": "Протягом літа ми працюємо до другої."}, {"hr": "Otvoreno je svaki dan osim nedjelje.", "ua": "Відчинено щодня, крім неділі."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('86621fe8-d207-5eab-9c37-0d741d6802d2', 'b7103d09-8e69-53f7-8f17-a90c771fa1a2', 'Кількість і час', 'Родовий відповідає на «скільки?» і «котрого числа?»: dva sata, pet eura, trećeg svibnja (третього травня), prošle godine (минулого року), svakog mjeseca. Типова помилка — «u prošlu godinu»: про час без прийменника кажемо родовий: Prošle godine sam se preselila.', 'prošle godine · svakog mjeseca · trećeg svibnja · do kraja tjedna', '[{"hr": "Porez se plaća do kraja mjeseca.", "ua": "Податок сплачують до кінця місяця."}, {"hr": "Prošle godine sam otvorila obrt.", "ua": "Минулого року я відкрила власну справу."}, {"hr": "Rok je petnaestog ožujka.", "ua": "Строк — п’ятнадцятого березня."}, {"hr": "Svakog mjeseca plaćam osiguranje.", "ua": "Щомісяця я плачу страховку."}]'::jsonb, 3)
on conflict (id) do nothing;
