  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = 'feaaa674-66e6-5521-ba6e-b5d1507cd351';
  update public.grammar_topics set title_ua = 'Perfekt: нагадування й вид у минулому', title_hr = 'Perfekt: podsjetnik i glagolski vid', description = 'Нагадування A1 (sam, si, je + -o / -la) і нове для A2: недоконаний і доконаний вид у минулому (čitao sam / pročitao sam), заперечення nisam, питання jesi li, порядок слів.', status = 'PUBLISHED'
   where id = 'feaaa674-66e6-5521-ba6e-b5d1507cd351';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('28299d43-07c4-52cf-a736-1f50432c3d31', 'feaaa674-66e6-5521-ba6e-b5d1507cd351', 'Нагадування: як утворюється perfekt', 'Perfekt = коротка форма biti (sam, si, je, smo, ste, su) + форма на -o / -la / -lo / -li: radio sam, radila sam, radili smo. Коротка форма стоїть на другому місці: Jučer sam radila. Якщо речення починається з дієслова — Radila sam jučer. Заперечення: nisam, nisi, nije… radio. Питання: Jesi li radio? Je li Darja došla?', 'radio / radila sam · nisam radio · Jesi li radio?', '[{"hr": "Jučer sam dugo radila.", "ua": "Учора я довго працювала."}, {"hr": "Nismo bili kod kuće.", "ua": "Нас не було вдома."}, {"hr": "Jesi li vidio Dašu?", "ua": "Ти бачив Дашу?"}, {"hr": "Djeca su se igrala u parku.", "ua": "Діти гралися в парку."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('f1f7d7f9-9374-517b-96fe-369c2513f60f', 'feaaa674-66e6-5521-ba6e-b5d1507cd351', 'Вид у минулому: čitao sam — pročitao sam', 'Недоконаний вид у perfekt — процес, тривалість, повторення в минулому: Kao dijete sam puno čitao (багато читав). Доконаний — завершена дія з результатом: Pročitao sam knjigu (прочитав до кінця). Тому з «svaki dan, često, dugo» — недоконаний, а з «jednom, konačno, napokon» — найчастіше доконаний.', 'Gledala sam film (процес). — Pogledala sam film (до кінця).', '[{"hr": "Ljeti smo svaki dan išli na more.", "ua": "Улітку ми щодня ходили на море."}, {"hr": "Jednom smo otišli na Hvar.", "ua": "Одного разу ми поїхали на Хвар."}, {"hr": "Dugo sam tražila stan.", "ua": "Я довго шукала квартиру."}, {"hr": "Napokon sam našla stan.", "ua": "Нарешті я знайшла квартиру."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('7aa9514d-43ef-5543-95d9-a1e3bb8ed66e', 'feaaa674-66e6-5521-ba6e-b5d1507cd351', 'Розповідь у минулому', 'У розповіді недоконаний вид дає «фон» (що відбувалося), доконаний — події, що йдуть одна за одною: Padala je kiša i čekala sam autobus. Odjednom je stao auto i izašao je Marko. Типова помилка українців — забута коротка форма: «Ja išao u školu» замість Išao sam u školu.', 'fon: bio je, padala je… · події: došao je, rekao je, otišao je', '[{"hr": "Sjedili smo u kafiću kad je počela oluja.", "ua": "Ми сиділи в кафе, коли почалася буря."}, {"hr": "Ušla sam, pozdravila i sjela.", "ua": "Я ввійшла, привіталася й сіла."}, {"hr": "Išao sam u školu pješice.", "ua": "Я ходив до школи пішки."}, {"hr": "Odjednom je nestala struja.", "ua": "Раптом зникло світло."}]'::jsonb, 3)
on conflict (id) do nothing;
