  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '4101ee05-3efe-5a98-a9e5-f0f327436268';
  update public.grammar_topics set title_ua = 'Зворотні дієслова: sjećati se, baviti se', title_hr = 'Povratni glagoli: sjećati se, baviti se', description = 'Нагадування A1 (se на другому місці) і нове для A2: керування зворотних дієслів (sjećati se + G, baviti se + I, bojati se + G, nadati se + D), se в perfekt (probudio sam se), дієслова із se без «-ся».', status = 'PUBLISHED'
   where id = '4101ee05-3efe-5a98-a9e5-f0f327436268';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('e5530da3-6688-5e68-aefa-0d87af19322a', '4101ee05-3efe-5a98-a9e5-f0f327436268', 'Se на другому місці — і в perfekt', 'У perfekt se стоїть після sam / si / smo / ste / su: Probudio sam se rano. Jesi li se odmorila? Лише в 3-й особі однини je випадає: Ona se probudila (не «se je»). Типова помилка українців — «Ja sam probudio se»: коротке слово завжди на другому місці.', 'Probudio sam se. · Ona se probudila. · Jesmo li se upoznali?', '[{"hr": "Jutros sam se probudila u pet.", "ua": "Сьогодні вранці я прокинулася о п’ятій."}, {"hr": "Luka se preselio u Zagreb.", "ua": "Лука переїхав до Загреба."}, {"hr": "Jeste li se dobro odmorili?", "ua": "Ви добре відпочили?"}, {"hr": "Upoznali smo se na fakultetu.", "ua": "Ми познайомилися в університеті."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c16f006f-1b5e-51e0-953c-4ef4b48eb6e5', '4101ee05-3efe-5a98-a9e5-f0f327436268', 'Керування: sjećati se + родовий', 'Деякі дієслова із se вимагають певного відмінка: sjećati se + G (згадувати, пам’ятати): sjećam se djetinjstva; bojati se + G: bojim se pasa; baviti se + I (займатися): bavim se sportom; nadati se + D (сподіватися): nadam se odgovoru. Українською «пам’ятаю дитинство» — знахідний, а хорватською — родовий.', 'sjećati se + G · bojati se + G · baviti se + I · nadati se + D', '[{"hr": "Sjećam se prvog dana u školi.", "ua": "Я пам’ятаю перший день у школі."}, {"hr": "Kao dijete sam se bojala mraka.", "ua": "У дитинстві я боялася темряви."}, {"hr": "Čime se baviš?", "ua": "Чим ти займаєшся?"}, {"hr": "Nadamo se brzom odgovoru.", "ua": "Сподіваємося на швидку відповідь."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('3cedf8df-4941-59a9-9637-9ab5a88c8320', '4101ee05-3efe-5a98-a9e5-f0f327436268', 'Se є, а «-ся» немає (і навпаки)', 'Часто se не збігається з українським «-ся»: smijati se — сміятися, але vratiti se — повернутися, sviđati se — подобатися, odlučiti se — наважитися, вирішити; razboljeti se — захворіти (без «-ся»!), dogoditi se — статися, odmarati se — відпочивати. Без se: početi — початися (Film je počeo).', 'razboljeti se — захворіти · dogoditi se — статися · početi — початися', '[{"hr": "Razboljela sam se prošli tjedan.", "ua": "Я захворіла минулого тижня."}, {"hr": "Što se dogodilo?", "ua": "Що сталося?"}, {"hr": "Odmaramo se na selu.", "ua": "Ми відпочиваємо в селі."}, {"hr": "Koncert je počeo u devet.", "ua": "Концерт почався о дев’ятій."}]'::jsonb, 3)
on conflict (id) do nothing;
