  update public.grammar_topics set title_ua = 'Орудний відмінок: множина й pred, iza, među', title_hr = 'Instrumental: množina i prijedlozi', description = 'Нагадування A1 (s prijateljem, autobusom) і нове для A2: орудний множини (s prijateljima, s djecom), прийменники pred, iza, među, nad, pod + орудний (де?), орудний займенників (sa mnom, s njim).', status = 'PUBLISHED'
   where id = 'd777c847-266e-57ef-a5a2-f417f12f1b3e';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('309a793e-9b11-5522-b1aa-a89448b98944', 'd777c847-266e-57ef-a5a2-f417f12f1b3e', 'Орудний множини: -ima, -ama', 'Чоловічий і середній рід у множині — -ima: s prijateljima, s kolegama (на -a — -ama), pred vratima. Жіночий — -ama: s ženama, sa sestrama. Неправильні: s ljudima, s djecom (діти — однина жін. роду: djeca → djecom), s braćom. Ці закінчення такі самі в давальному й місцевому множини.', 's prijateljima · s kolegama · sa sestrama · s djecom · s ljudima', '[{"hr": "Ljeto provodim s prijateljima.", "ua": "Літо я проводжу з друзями."}, {"hr": "Došla je s djecom.", "ua": "Вона прийшла з дітьми."}, {"hr": "Dobro se slažem s kolegama.", "ua": "Я добре ладнаю з колегами."}, {"hr": "Razgovarali smo s ljudima iz udruge.", "ua": "Ми поговорили з людьми з асоціації."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9cb52d46-424f-51e6-b502-d672aab9615b', 'd777c847-266e-57ef-a5a2-f417f12f1b3e', 'Pred, iza, među, nad, pod — де?', 'На питання gdje? ці прийменники — з орудним: pred kućom (перед будинком), iza zgrade (iza — з родовим!), među prijateljima (серед друзів), nad stolom, pod stolom. Куди? — зі знахідним: Stavi torbu pod stol. Типова помилка: iza — завжди родовий (iza kuće), а pred, među, nad, pod — орудний.', 'pred + I · među + I · nad + I · pod + I · iza + G', '[{"hr": "Čekam te pred kinom.", "ua": "Чекаю тебе перед кінотеатром."}, {"hr": "Među gostima je bilo puno djece.", "ua": "Серед гостей було багато дітей."}, {"hr": "Mačka spava pod stolom.", "ua": "Кіт спить під столом."}, {"hr": "Parkiralište je iza zgrade.", "ua": "Парковка за будинком."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('3445017e-0137-5e60-b4b7-ca9425bfec19', 'd777c847-266e-57ef-a5a2-f417f12f1b3e', 'Займенники: sa mnom, s njim, s njom', 'Орудний займенників: mnom, tobom, njim, njom, nama, vama, njima. З приголосним s → sa перед mnom: sa mnom. Idi s njim. Razgovarala sam s njom. Ne mogu bez tebe — це родовий; s tobom — орудний.', 'sa mnom · s tobom · s njim · s njom · s nama · s vama · s njima', '[{"hr": "Hoćeš li ići sa mnom?", "ua": "Підеш зі мною?"}, {"hr": "Svađala sam se s njim.", "ua": "Я сварилася з ним."}, {"hr": "Drago mi je raditi s vama.", "ua": "Мені приємно працювати з вами."}, {"hr": "Pričaj s njom.", "ua": "Поговори з нею."}]'::jsonb, 3)
on conflict (id) do nothing;
