  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '78491f05-4871-51e6-aa8e-7f81fe2f6099';
  update public.grammar_topics set title_ua = 'Давальний відмінок: повні форми й множина', title_hr = 'Dativ: puni oblici i množina', description = 'Нагадування A1 (mi, ti, mu, joj) і нове для A2: давальний іменників в однині й множині (mami, bratu, ljudima, djeci), дієслова з давальним (pomoći, poslati, vjerovati), прийменники prema, k.', status = 'PUBLISHED'
   where id = '78491f05-4871-51e6-aa8e-7f81fe2f6099';
