insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('875a087d-3c12-5ce6-8998-11242575ff7e', '78491f05-4871-51e6-aa8e-7f81fe2f6099', 'Кому? Давальний іменників', 'Однина: чоловічий і середній — -u (bratu, Ivanu, djetetu), жіночий — -i (mami, Darji, prijateljici). Множина — -ima / -ama (ljudima, kolegama, sestrama), djeca → djeci. Давальний — адресат дії: Šaljem paket mami. Pomažem susjedu. Типова помилка — «Pomažem susjeda» (знахідний): pomagati / pomoći — з давальним.', 'mami · bratu · Darji · djeci · ljudima · sestrama', '[{"hr": "Šaljem paket mami u Kijev.", "ua": "Надсилаю посилку мамі до Києва."}, {"hr": "Pomogli smo susjedima s preseljenjem.", "ua": "Ми допомогли сусідам з переїздом."}, {"hr": "Kupila sam djeci nove knjige.", "ua": "Я купила дітям нові книжки."}, {"hr": "Vjerujem prijateljima.", "ua": "Я довіряю друзям."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('8356ac60-8baf-51eb-a7a4-50ffd871a0c7', '78491f05-4871-51e6-aa8e-7f81fe2f6099', 'Дієслова з давальним', 'З давальним: pomoći / pomagati (допомогти), poslati (надіслати кому), dati, reći, objasniti, vjerovati (вірити кому), zahvaliti (дякувати кому), čestitati (вітати кого), javiti (повідомити). Українською «вітаю маму» — знахідний, а хорватською Čestitam mami — давальний.', 'pomoći + D · čestitati + D · zahvaliti + D · javiti se + D', '[{"hr": "Čestitala sam baki rođendan.", "ua": "Я привітала бабусю з днем народження."}, {"hr": "Zahvaljujemo svim volonterima.", "ua": "Дякуємо всім волонтерам."}, {"hr": "Javi se roditeljima.", "ua": "Озвися до батьків."}, {"hr": "Objasnite mi, molim Vas, kako to funkcionira.", "ua": "Поясніть мені, будь ласка, як це працює."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('373c5fbf-a70e-53ab-8045-6ec52e12edee', '78491f05-4871-51e6-aa8e-7f81fe2f6099', 'Prema і k (ka)', 'Prema + давальний — «до, у напрямку» і «щодо, згідно з»: Idemo prema moru. Prema zakonu… Ljubazan je prema svima. K / ka + давальний — «до (людини)»: Idem k liječniku. Ka — перед k, g і перед meni: ka kući, ka meni. У розмові частіше kod / do / na, але prema в офіційних текстах — дуже часто.', 'prema moru · prema zakonu · k liječniku · ka meni', '[{"hr": "Prema novom zakonu, rok je trideset dana.", "ua": "Згідно з новим законом строк — тридцять днів."}, {"hr": "Hodali smo prema centru.", "ua": "Ми йшли в бік центру."}, {"hr": "Bila je vrlo ljubazna prema nama.", "ua": "Вона була дуже привітна з нами."}, {"hr": "Sutra idem k zubaru.", "ua": "Завтра я йду до стоматолога."}]'::jsonb, 3)
on conflict (id) do nothing;
