do $$
begin
  if not exists (select 1 from public.grammar_topics where id = '17b75bc6-fca0-5f09-830c-ab7f37279022') then raise exception 'Немає теми граматики A2 FUT'; end if;
  if exists (select 1 from public.grammar_rules where topic_id = '17b75bc6-fca0-5f09-830c-ab7f37279022') then return; end if;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'grammar_topic', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'grammar_topic' and entity_id = x.id), 0) + 1,
         to_jsonb(x), 'curriculum_a2_v2: тема A2 отримує правила (нова назва й опис) — стара версія' from public.grammar_topics x where x.id = '17b75bc6-fca0-5f09-830c-ab7f37279022';
  update public.grammar_topics set title_ua = 'Futur I: нагадування й доконаний вид', title_hr = 'Futur I.: podsjetnik i svršeni glagoli', description = 'Нагадування A1 (ću, ćeš, će + інфінітив; ići ću) і нове для A2: доконаний вид у майбутньому (nazvat ću, javit ću se), вирази vidjet ćemo se, bit će, порядок слів.', status = 'PUBLISHED'
   where id = '17b75bc6-fca0-5f09-830c-ab7f37279022';
end $$;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9f43a047-c800-5bd8-a8e7-7545c10f6aa9', '17b75bc6-fca0-5f09-830c-ab7f37279022', 'Нагадування: ću + інфінітив', 'Futur I = ću, ćeš, će, ćemo, ćete, će + інфінітив. Якщо дієслово стоїть першим, інфінітив втрачає -i і пишеться разом: radit ću, nazvat ćemo (але на -ći — ići ću, doći ću). Якщо першим стоїть інше слово — Sutra ću raditi. Заперечення: neću, nećeš… — Neću doći.', 'Radit ću. — Sutra ću raditi. — Neću raditi. — Hoćeš li raditi?', '[{"hr": "Sutra ću ti poslati poruku.", "ua": "Завтра надішлю тобі повідомлення."}, {"hr": "Javit ću se kad stignem.", "ua": "Я озвуся, коли приїду."}, {"hr": "Nećemo stići na vrijeme.", "ua": "Ми не встигнемо вчасно."}, {"hr": "Hoćeš li doći na zabavu?", "ua": "Ти прийдеш на вечірку?"}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c6acd941-052d-5c02-b035-a102c02f6c9a', '17b75bc6-fca0-5f09-830c-ab7f37279022', 'Доконаний чи недоконаний у майбутньому', 'Доконане дієслово — одна дія з результатом: Završit ću projekt do petka. Недоконане — процес чи повторення: Radit ću na projektu cijeli tjedan. Типова помилка — «Ja budu raditi» (як українське «буду працювати»): у хорватському futur I завжди ću + інфінітив; budem — лише у futur II.', 'Napisat ću (один раз). — Pisat ću (часто, довго).', '[{"hr": "Završit ću tečaj do lipnja.", "ua": "Я закінчу курс до червня."}, {"hr": "Učit ću svaki dan po pola sata.", "ua": "Я вчитимуся щодня по пів години."}, {"hr": "Pomoći ću ti s preseljenjem.", "ua": "Я допоможу тобі з переїздом."}, {"hr": "Gledat ćemo seriju cijeli vikend.", "ua": "Ми дивитимемося серіал усі вихідні."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('e55f994c-7992-5f42-b4ae-7050caeb8d46', '17b75bc6-fca0-5f09-830c-ab7f37279022', 'Сталі вирази', 'Vidjet ćemo (побачимо), Vidimo se! / Vidjet ćemo se (побачимося), Bit će (буде), Bit će bolje (буде краще), Javit ću ti (повідомлю), Bit ću tamo (я там буду). Bit će часто означає здогад: Bit će da je zaboravio (мабуть, він забув).', 'Vidjet ćemo. · Bit će bolje. · Bit će da…', '[{"hr": "Ne znam još, vidjet ćemo.", "ua": "Ще не знаю, побачимо."}, {"hr": "Ne brini, bit će sve u redu.", "ua": "Не хвилюйся, усе буде гаразд."}, {"hr": "Vidjet ćemo se sutra na poslu.", "ua": "Побачимося завтра на роботі."}, {"hr": "Bit ću kod kuće iza šest.", "ua": "Я буду вдома після шостої."}]'::jsonb, 3)
on conflict (id) do nothing;
