insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('6de8bf6e-97a1-5cb3-8e31-538b07c36309', 'A2', 'Множина: давальний, місцевий, орудний', 'Množina: dativ, lokativ, instrumental', 'Однакові закінчення множини в давальному, місцевому й орудному: -ima для чоловічого й середнього роду (u gradovima, s ljudima), -ama для жіночого (u školama), неправильні djeci, ljudima, braći.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('321af1b3-96af-5882-b4fc-83cb2af3e78c', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', 'Одне закінчення на три відмінки', 'У множині давальний, місцевий і орудний збігаються: чоловічий і середній рід — -ima (gradovima, selima, ljudima), жіночий на -a — -ama (školama, ulicama), жіночий на приголосний — -ima (stvarima). Отже: pomoći ljudima, živjeti među ljudima, razgovarati s ljudima — одна форма.', 'D = L = I: gradovima · ulicama · stvarima · ljudima', '[{"hr": "U većim gradovima ima puno buke.", "ua": "У великих містах багато шуму."}, {"hr": "Pomažemo starijim ljudima.", "ua": "Ми допомагаємо літнім людям."}, {"hr": "Na ulicama je bilo smeća.", "ua": "На вулицях було сміття."}, {"hr": "Razgovarala sam sa susjedima.", "ua": "Я поговорила із сусідами."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('bdcd53c8-1280-5931-8bb5-9cec95292158', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', 'Прикметники в множині: -im, -ima', 'Прикметник у D / L / I множини — -im або -ima для всіх родів: u velikim gradovima / u velikima, s novim susjedima, u starim kućama. Займенники: mojim prijateljima, ovim ljudima, tim ulicama. Типова помилка — «u veliki gradovi» (називний замість місцевого).', 'u velikim gradovima · s novim susjedima · u starim kućama', '[{"hr": "Smeće se odvaja u posebnim kantama.", "ua": "Сміття сортують в окремих контейнерах."}, {"hr": "U starim kućama je hladno zimi.", "ua": "У старих будинках узимку холодно."}, {"hr": "Pišem svojim prijateljima u Ukrajini.", "ua": "Я пишу своїм друзям в Україні."}, {"hr": "Na ovim plažama nema hlada.", "ua": "На цих пляжах немає тіні."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('796fecac-09ad-5f49-86e3-8ab4f62cd02a', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', 'Неправильні форми', 'Деякі слова мають особливу множину: ljudi → ljudima, djeca → djeci (D, L), djecom (I) — бо djeca відмінюється як жіночий рід однини; braća → braći, braćom; oči → očima, uši → ušima; prsti → prstima. Na rukama, na nogama — регулярно.', 'djeci / djecom · braći / braćom · očima · ušima', '[{"hr": "Pričam djeci priču prije spavanja.", "ua": "Я розповідаю дітям казку перед сном."}, {"hr": "Idem na izlet s djecom.", "ua": "Я йду на екскурсію з дітьми."}, {"hr": "Vidjela sam to svojim očima.", "ua": "Я бачила це на власні очі."}, {"hr": "Nosim rukavice na rukama.", "ua": "Я ношу рукавички на руках."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '6de8bf6e-97a1-5cb3-8e31-538b07c36309' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('879e6305-0f75-5e88-abff-e27819f2d92d', 'A2', 'Звукові зміни: рухоме a, u ruci, mlađi', 'Glasovne promjene', 'Найчастіші звукові зміни, без яких важко відмінювати: рухоме a (momak – momka), сибіляризація (ruka – u ruci, noga – na nozi), йотування у вищому ступені (mlad – mlađi, brz – brži), k / g / h перед i.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9399be8c-3510-5e3a-8afc-b267dd62b1fc', '879e6305-0f75-5e88-abff-e27819f2d92d', 'Рухоме a', 'У багатьох іменниках чоловічого роду a в останньому складі зникає, коли додаємо закінчення: momak → momka, pas → psa, novac → novca, lakat → lakta, vrabac → vrapca. І навпаки, у родовому множини a з’являється: djevojka → djevojaka, pismo → pisama. Схоже на українське «сон — сну».', 'pas → psa · novac → novca · lakat → lakta · djevojka → djevojaka', '[{"hr": "Boli me ruka od lakta do ramena.", "ua": "У мене болить рука від ліктя до плеча."}, {"hr": "Nemam dovoljno novca za taj lijek.", "ua": "У мене не вистачає грошей на ці ліки."}, {"hr": "Bojim se psa od susjeda.", "ua": "Я боюся сусідського собаки."}, {"hr": "Na tečaju je bilo deset djevojaka.", "ua": "На курсі було десять дівчат."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('1c5594b4-9e78-55c4-a78c-71b4105d0200', '879e6305-0f75-5e88-abff-e27819f2d92d', 'K, g, h → c, z, s: u ruci, na nozi', 'Перед -i в давальному й місцевому однини жіночого роду k, g, h змінюються: ruka → u ruci, noga → na nozi, knjiga → u knjizi, majka → majci. У множині чоловічого роду: liječnik → liječnici, bubreg → bubrezi. Як в українському «рука — у руці, нога — на нозі».', 'ruka → u ruci · noga → na nozi · knjiga → u knjizi · liječnik → liječnici', '[{"hr": "Imam ranu na nozi.", "ua": "У мене рана на нозі."}, {"hr": "Drži lijekove u ruci.", "ua": "Він тримає ліки в руці."}, {"hr": "Liječnici rade i vikendom.", "ua": "Лікарі працюють і на вихідних."}, {"hr": "Pročitala sam to u knjizi.", "ua": "Я прочитала це в книжці."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('cb08662e-da0d-5d06-8b2d-9bdfef028c23', '879e6305-0f75-5e88-abff-e27819f2d92d', 'Йотування: mlađi, brži, skuplji', 'У вищому ступені прикметника j зливається з приголосним: mlad → mlađi, brz → brži, skup → skuplji, tih → tiši, drag → draži, jak → jači, visok → viši. Тому «mladiji» чи «skupiji» — помилка. Те саме у формах дієслів: pisati → pišem, kazati → kažem.', 'mlad → mlađi · skup → skuplji · jak → jači · tih → tiši', '[{"hr": "Moj brat je dvije godine mlađi.", "ua": "Мій брат на два роки молодший."}, {"hr": "Bol je danas jača nego jučer.", "ua": "Біль сьогодні сильніший, ніж учора."}, {"hr": "Privatni pregled je skuplji.", "ua": "Приватний огляд дорожчий."}, {"hr": "Ovdje je tiše, možemo razgovarati.", "ua": "Тут тихіше, можемо поговорити."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '879e6305-0f75-5e88-abff-e27819f2d92d', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '879e6305-0f75-5e88-abff-e27819f2d92d' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('b5076495-20a1-53e5-be78-eee365980865', 'A2', 'Множина з розширенням: gradovi, djeca, braća', 'Množina s proširenjem: gradovi, djeca, braća', 'Множина односкладових іменників з -ov- / -ev- (grad – gradovi, muž – muževi), неправильні множини (čovjek – ljudi, dijete – djeca, brat – braća), середній рід із розширенням (ime – imena, rame – ramena).', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('97a298bb-a9c1-58f9-84ae-04e9c052718b', 'b5076495-20a1-53e5-be78-eee365980865', 'Gradovi, muževi: -ovi / -evi', 'Більшість односкладових іменників чоловічого роду в множині отримують -ov- або -ev- (-ev- після č, ć, đ, š, ž, j, lj, nj, c): grad → gradovi, stol → stolovi, sin → sinovi, muž → muževi, kralj → kraljevi, nož → noževi. Виняток: zub → zubi, gost → gosti, konj → konji.', 'grad → gradovi · sin → sinovi · muž → muževi · gost → gosti', '[{"hr": "Moji sinovi idu u istu školu.", "ua": "Мої сини ходять до тієї самої школи."}, {"hr": "Gosti dolaze u sedam.", "ua": "Гості приходять о сьомій."}, {"hr": "Muževi su kuhali, a žene su plesale.", "ua": "Чоловіки куховарили, а жінки танцювали."}, {"hr": "U sobi su dva stola.", "ua": "У кімнаті два столи."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('59a23341-4471-5cd1-a448-6567c727fe5a', 'b5076495-20a1-53e5-be78-eee365980865', 'Ljudi, djeca, braća', 'Неправильні множини: čovjek → ljudi (люди), dijete → djeca (діти), brat → braća (брати), gospodin → gospoda. Djeca і braća відмінюються як жіночий рід однини, але дієслово — у множині: Djeca su sretna. Braća su došla. Типова помилка — «djeca je»: дієслово завжди в множині.', 'čovjek → ljudi · dijete → djeca · brat → braća · gospodin → gospoda', '[{"hr": "Djeca su se igrala u dvorištu.", "ua": "Діти гралися у дворі."}, {"hr": "Moja braća žive u Lavovu.", "ua": "Мої брати живуть у Львові."}, {"hr": "Na svadbi je bilo dvjesto ljudi.", "ua": "На весіллі було двісті людей."}, {"hr": "Dame i gospodo, dobrodošli!", "ua": "Пані й панове, ласкаво просимо!"}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('32a11550-3c12-5a4b-adcc-db33b68260c2', 'b5076495-20a1-53e5-be78-eee365980865', 'Ime – imena: середній рід із розширенням', 'Деякі іменники середнього роду мають у відмінках -en- або -et-: ime → imena (ім’я — імені), rame → ramena, vrijeme → vremena, dijete → djeteta, tele → teleta. Як в українському «ім’я — імені, теля — теляти».', 'ime → imena · vrijeme → vremena · rame → ramena · dijete → djeteta', '[{"hr": "Kako se piše tvoje ime?", "ua": "Як пишеться твоє ім’я?"}, {"hr": "Nemam vremena za kavu.", "ua": "У мене немає часу на каву."}, {"hr": "Upisali smo imena svih gostiju.", "ua": "Ми записали імена всіх гостей."}, {"hr": "Boli me rame.", "ua": "У мене болить плече."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', 'b5076495-20a1-53e5-be78-eee365980865', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = 'b5076495-20a1-53e5-be78-eee365980865' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('6da44157-69d7-5261-8289-fe910fd60f59', 'A2', 'Присвійні прикметники й прикметники від назв місць', 'Posvojni pridjevi', 'Присвійні прикметники від імен і людей (Ivanov, Darjin, mamin, bratov) і прикметники від назв місць (istarski, slavonski, zagrebački, dalmatinski): утворення, рід, мала літера.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('f000ac78-fab4-5ebf-8f6c-4e67c3270fc2', '6da44157-69d7-5261-8289-fe910fd60f59', 'Ivanov, Darjin: чий?', 'Від імен і слів про людей утворюємо прикметник: на приголосний — -ov / -ev (Ivan → Ivanov, Marko → Markov, Luka → Lukin), на -a — -in (Darja → Darjin, mama → mamin, sestra → sestrin). Він узгоджується з іменником: Darjin auto, Darjina kuća, Darjino dijete. В українській є те саме: Іванів, мамин.', 'Ivan → Ivanov · Darja → Darjin · mama → mamin · brat → bratov', '[{"hr": "Ovo je Darjin bicikl.", "ua": "Це Дар’їн велосипед."}, {"hr": "Bakina kuća je u Slavoniji.", "ua": "Бабусин будинок у Славонії."}, {"hr": "Probaj mamine kolače!", "ua": "Скуштуй маминих тістечок!"}, {"hr": "Markov otac je ribar.", "ua": "Марків батько — рибалка."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9bbb3774-d821-50dd-88f8-9bbc66221cf7', '6da44157-69d7-5261-8289-fe910fd60f59', 'Istarski, slavonski: прикметники від місць', 'Від назв країв і міст — -ski / -ški / -čki: Istra → istarski, Slavonija → slavonski, Dalmacija → dalmatinski, Zagreb → zagrebački, Split → splitski, Rijeka → riječki. Пишуться з малої літери: istarski pršut, slavonski kulen. Лише в назвах — з великої: Istarska županija.', 'Istra → istarski · Zagreb → zagrebački · Lika → lički · Zagorje → zagorski', '[{"hr": "Probali smo istarski tartuf.", "ua": "Ми скуштували істрійський трюфель."}, {"hr": "Slavonski kulen je jako ljut.", "ua": "Славонський кулен дуже гострий."}, {"hr": "Zagrebačka katedrala se obnavlja.", "ua": "Загребський собор реставрують."}, {"hr": "Ovo je tipična dalmatinska kuća.", "ua": "Це типовий далматинський будинок."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('1a974acc-d062-5509-abc9-d2ed1d3ef043', '6da44157-69d7-5261-8289-fe910fd60f59', 'Відмінювання', 'Присвійні прикметники відмінюються як звичайні: u Darjinom stanu, s maminim autom, iz bakine kuhinje. Прикметники від місць — так само: u istarskim selima, na zagrebačkoj tržnici. Типова помилка — родовий «auto od Darje» замість Darjin auto: це можливо в розмові, але природніше прикметник.', 'u Darjinom stanu · s maminim autom · na zagrebačkoj tržnici', '[{"hr": "Spavali smo u bakinoj sobi.", "ua": "Ми спали в бабусиній кімнаті."}, {"hr": "Vozim se bratovim autom.", "ua": "Я їжджу братовою машиною."}, {"hr": "U istarskim selima je mirno.", "ua": "В істрійських селах тихо."}, {"hr": "Kupila sam sir na zagrebačkoj tržnici.", "ua": "Я купила сир на загребському ринку."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '6da44157-69d7-5261-8289-fe910fd60f59', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '6da44157-69d7-5261-8289-fe910fd60f59' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('d1e0a0ca-707a-5b16-bcdf-06037cb17e0e', 'A2', 'Числа: 2–4, збірні, oba / obje, дати', 'Brojevi: 2–4, zbirni brojevi, datumi', 'Іменник після 2, 3, 4 (dva brata, tri sestre), збірні числівники для людей і дітей (dvoje djece, troje), oba / obje / oboje, порядкові числа в датах і роках (rođena sam 1990. godine).', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('fa224982-dac7-5fb3-9c22-77f38203628f', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', '2, 3, 4 + іменник', 'Після dva / dvije, tri, četiri: чоловічий і середній рід — форма на -a (dva brata, tri sela), жіночий — -e (dvije sestre, četiri kuće). Dva — для чоловічого й середнього, dvije — для жіночого роду. Від 5 — родовий множини: pet braće, pet sestara. Прикметник: dva mala grada, dvije male kuće.', 'dva brata · dvije sestre · tri godine · četiri sela · pet godina', '[{"hr": "Imam dva brata i dvije sestre.", "ua": "У мене два брати й дві сестри."}, {"hr": "Živjeli smo tamo tri godine.", "ua": "Ми жили там три роки."}, {"hr": "Preselili smo se prije četiri mjeseca.", "ua": "Ми переїхали чотири місяці тому."}, {"hr": "U razredu je dvadeset dva učenika.", "ua": "У класі двадцять два учні."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('f7c286cb-c8c3-5cdb-ada0-a96989761148', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', 'Збірні: dvoje, troje, četvero', 'Для дітей, змішаних груп (чоловік і жінка) і слів у множині — збірні числівники + родовий множини: dvoje djece, troje ljudi, četvero unučadi; stol za četvero. Oba (обидва), obje (обидві), oboje (обоє — він і вона): Oboje rade u Zagrebu. Українською: «двоє дітей» — те саме.', 'dvoje djece · troje · četvero · oba / obje / oboje', '[{"hr": "Imamo dvoje djece.", "ua": "У нас двоє дітей."}, {"hr": "Rezervirala sam stol za četvero.", "ua": "Я забронювала столик на чотирьох."}, {"hr": "Oboje smo završili fakultet u Kijevu.", "ua": "Ми обоє закінчили університет у Києві."}, {"hr": "Obje sestre žive u Splitu.", "ua": "Обидві сестри живуть у Спліті."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('aee89ee0-2a98-5b3c-9934-c6f32674b719', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', 'Дати й роки', 'Дата — порядкове число в родовому: Rođen sam petog svibnja (п’ятого травня). Рік: tisuću devetsto devedesete (1990.) або dvije tisuće dvadeset druge (2022.); на письмі після числа — крапка: 1990. godine, 5. 5. 2022. Коли? — u + місцевий для місяця (u svibnju), godine + родовий для року.', 'petog svibnja · 1990. godine · u svibnju · od 2022. do 2024.', '[{"hr": "Rođena sam dvadeset prvog travnja.", "ua": "Я народилася двадцять першого квітня."}, {"hr": "U Hrvatsku smo došli 2022. godine.", "ua": "До Хорватії ми приїхали 2022 року."}, {"hr": "Vjenčali smo se u lipnju.", "ua": "Ми одружилися в червні."}, {"hr": "Prvog rujna djeca kreću u školu.", "ua": "Першого вересня діти йдуть до школи."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('3a13fbe7-c0e4-55f8-b938-5579165e11bf', 'A2', 'Дієслова руху з префіксами', 'Glagoli kretanja s prefiksima', 'Префікси при ići і voziti: doći, otići, ući, izaći, prijeći, proći, zaći, obići; dovesti, odvesti, prevesti; пари доконаного й недоконаного виду (dolaziti / doći), прийменники після них.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9e060df4-7593-559a-b4d4-4b70eb458238', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', 'Do-, od-, u-, iz-: прийти, піти, увійти, вийти', 'Від ići: doći (прийти, приїхати), otići (піти, поїхати), ući (увійти, заїхати), izaći (вийти, виїхати), prijeći (перейти), proći (пройти, проїхати), obići (обійти, оглянути). Теперішній час: dođem, odem, uđem, izađem, prijeđem, prođem. Недоконаний вид: dolaziti, odlaziti, ulaziti, izlaziti, prelaziti, prolaziti.', 'doći · otići · ući · izaći · prijeći · proći — dolaziti · odlaziti · ulaziti …', '[{"hr": "Izađite na drugom izlazu.", "ua": "Виїжджайте на другому з’їзді."}, {"hr": "Prošli smo kroz crveno?", "ua": "Ми проїхали на червоне?"}, {"hr": "Pazi kad prelaziš cestu.", "ua": "Будь уважний, коли переходиш дорогу."}, {"hr": "Ušao je u raskrižje prebrzo.", "ua": "Він заїхав на перехрестя надто швидко."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('455f6998-5da7-5c7d-a2d3-00b24a60c1cc', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', 'Звідки й куди після префікса', 'Префікс підказує прийменник: ući u + знахідний (ući u auto), izaći iz + родовий (izaći iz auta), doći do + родовий (doći do granice) або na / u + знахідний (doći na posao), otići od + родовий (otići od kuće), prijeći preko + родовий (prijeći preko mosta). Українці часто кажуть «izaći s auta» — правильно iz auta.', 'ući u + A · izaći iz + G · doći do + G · prijeći preko + G', '[{"hr": "Izašla sam iz auta i nazvala policiju.", "ua": "Я вийшла з машини й подзвонила в поліцію."}, {"hr": "Kako da dođem do granice?", "ua": "Як мені доїхати до кордону?"}, {"hr": "Prijeđite preko mosta i skrenite lijevo.", "ua": "Переїдьте міст і поверніть ліворуч."}, {"hr": "Uđite u traku za Rijeku.", "ua": "Займіть смугу на Рієку."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('b87a4fae-4782-5b46-814f-3463034a3f59', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', 'Voziti, vesti, nositi з префіксами', 'Ті самі префікси при voziti (їхати, везти), voditi / vesti (вести), nositi (нести): dovesti (привести, привезти), odvesti (відвезти), prevesti (перевезти), donijeti (принести), odnijeti (віднести). Vozilo su odvezli na parkiralište. Pauk je odvezao auto — евакуатор забрав машину.', 'dovesti · odvesti · prevesti · donijeti · odnijeti · zaobići', '[{"hr": "Pauk mi je odvezao auto.", "ua": "Евакуатор забрав мою машину."}, {"hr": "Možete li me odvesti do servisa?", "ua": "Чи можете ви відвезти мене до сервісу?"}, {"hr": "Donesite prometnu dozvolu.", "ua": "Принесіть свідоцтво про реєстрацію."}, {"hr": "Zaobiđite centar zbog radova.", "ua": "Об’їдьте центр через ремонтні роботи."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '3a13fbe7-c0e4-55f8-b938-5579165e11bf' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('9c01b59a-6b4f-52a9-abfd-d78278072098', 'A2', 'Безособові речення: Muka mi je, Ne da mi se', 'Bezlične rečenice', 'Безособові конструкції з давальним (Muka mi je, Hladno mi je, Teško mi je, Ne da mi se, Spava mi se) і з se (Čini mi se, Ovdje se dobro jede); дієслово в 3-й особі однини середнього роду в минулому.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('8963205f-e0c5-549e-9a49-cc85f2c9ff27', '9c01b59a-6b4f-52a9-abfd-d78278072098', 'Muka mi je, hladno mi je', 'Стан людини: давальний + je + прислівник: Muka mi je (мене нудить), Hladno mi je (мені холодно), Teško mi je (мені важко), Bolje mi je (мені краще), Žao mi je (мені шкода). Без займенника «ja»: не «Ja sam hladno». У минулому — bilo je: Bilo mi je loše. Буде — bit će: Bit će ti bolje.', 'Muka mi je. · Bilo mi je loše. · Bit će ti bolje.', '[{"hr": "Muka mi je od vožnje.", "ua": "Мене нудить від їзди."}, {"hr": "Jučer mi je bilo jako loše.", "ua": "Учора мені було дуже погано."}, {"hr": "Je li ti hladno?", "ua": "Тобі холодно?"}, {"hr": "Danas mi je puno bolje.", "ua": "Сьогодні мені набагато краще."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('20401c3c-b790-5573-921e-b76e62bca170', '9c01b59a-6b4f-52a9-abfd-d78278072098', 'Ne da mi se, spava mi se', 'Ne da mi se + інфінітив — «мені не хочеться, лінь»: Ne da mi se kuhati. Spava mi se — хочеться спати, jede mi se — хочеться їсти, plače mi se — хочеться плакати. Зверніть увагу: дієслово в 3-й особі однини + se + давальний: Djeci se spava.', 'Ne da mi se… · Spava mi se. · Ide mi se van.', '[{"hr": "Ne da mi se danas ići na trening.", "ua": "Мені сьогодні не хочеться йти на тренування."}, {"hr": "Spava mi se, rano sam ustala.", "ua": "Мені хочеться спати, я рано встала."}, {"hr": "Djeci se ne spava.", "ua": "Дітям не хочеться спати."}, {"hr": "Pije mi se nešto hladno.", "ua": "Мені хочеться випити чогось холодного."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('f6c8d98c-e1b8-5329-a8c9-3b5f7c88fca1', '9c01b59a-6b4f-52a9-abfd-d78278072098', 'Čini mi se, ovdje se…', 'Čini mi se da… (мені здається, що…), Čuje se (чути), Vidi se (видно), Zna se (відомо). Ovdje se dobro jede (тут добре годують). Kako se kaže…? (Як сказати…?). Дієслово — у 3-й особі однини. Типова помилка — «Mi se čini»: коротке mi не стоїть на початку.', 'Čini mi se da… · Vidi se da… · Kako se kaže…?', '[{"hr": "Čini mi se da imam temperaturu.", "ua": "Мені здається, що в мене температура."}, {"hr": "Vidi se da si umorna.", "ua": "Видно, що ти втомлена."}, {"hr": "Kako se kaže «лікарняний» na hrvatskom?", "ua": "Як сказати «лікарняний» хорватською?"}, {"hr": "Ovdje se ne puši.", "ua": "Тут не курять."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '9c01b59a-6b4f-52a9-abfd-d78278072098', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '9c01b59a-6b4f-52a9-abfd-d78278072098' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('a6dba6b3-0b0a-588c-acd4-7eedced88519', 'A2', 'Пасив із se: Zahtjev se predaje…', 'Pasiv sa se', 'Безособовий пасив із se для правил, інструкцій і оголошень (Zahtjev se predaje na šalteru, Ovdje se plaća karticom): дієслово узгоджується з іменником; пасивний дієприкметник (zatvoreno, otvoren, potpisan).', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('c502abba-eeeb-560a-8535-2a201800e39a', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', 'Se для правил і інструкцій', 'Коли не важливо, хто робить дію, хорвати кажуть дієслово + se: Zahtjev se predaje na šalteru (заяву подають у віконці). Prijava se šalje e-mailom. Ovdje se plaća karticom. Дієслово узгоджується з іменником: Dokumenti se predaju… (множина). Українською — «подають», «подається».', 'Zahtjev se predaje… · Dokumenti se predaju… · Ovdje se ne parkira.', '[{"hr": "Upisnina se plaća unaprijed.", "ua": "Вступний внесок сплачують наперед."}, {"hr": "Prijave se primaju do petka.", "ua": "Заявки приймають до п’ятниці."}, {"hr": "Kako se ispunjava ovaj obrazac?", "ua": "Як заповнюють цей бланк?"}, {"hr": "U knjižnici se ne razgovara glasno.", "ua": "У бібліотеці не розмовляють голосно."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('6033d040-9e6c-55d9-bc6c-3895d8862274', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', 'Zatvoreno, otvoren: дієприкметник', 'На вивісках і в документах — пасивний дієприкметник: otvoreno / zatvoreno, potpisan ugovor (підписаний договір), plaćeno (оплачено), zabranjeno pušenje. З biti: Ugovor je potpisan. Zahtjev je odbijen. Ured je zatvoren zbog praznika.', 'zatvoreno · plaćeno · potpisan · odobren · odbijen', '[{"hr": "Vaš zahtjev je odobren.", "ua": "Вашу заяву схвалено."}, {"hr": "Račun je plaćen jučer.", "ua": "Рахунок оплачено вчора."}, {"hr": "Diploma mora biti ovjerena.", "ua": "Диплом має бути засвідчений."}, {"hr": "Trgovina je zatvorena nedjeljom.", "ua": "Магазин зачинений у неділю."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('7487595c-0c5d-5e6e-9f70-f482440cc585', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', 'Se чи особа?', 'Порівняйте: Predajem zahtjev (я подаю) — Zahtjev se predaje (заяву подають). Na tečaju se puno govori (на курсі багато говорять). Типова помилка — «Zahtjev predaje se»: se — на другому місці, після першого слова чи групи: Zahtjev se predaje.', 'Predajem zahtjev. — Zahtjev se predaje. — Na tečaju se govori.', '[{"hr": "Na ovom tečaju se puno piše.", "ua": "На цьому курсі багато пишуть."}, {"hr": "Ispit se polaže u lipnju.", "ua": "Іспит складають у червні."}, {"hr": "Na fakultetu se upisuje u srpnju.", "ua": "До університету вступають у липні."}, {"hr": "Ovdje se predaju molbe za stipendiju.", "ua": "Тут подають заяви на стипендію."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = 'a6dba6b3-0b0a-588c-acd4-7eedced88519' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('ec75057c-1f8d-51e1-9946-1ff5bbfeebca', 'A2', 'Порядок коротких слів (енклітик)', 'Red riječi: enklitike', 'Короткі ненаголошені слова (li, bih / sam / ću, mi / ti / mu, me / te / ga, se, je) стоять на другому місці в певному порядку: Dao sam mu ga. Javit ću ti se. Je li ti rekao?', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('454c83b9-a988-5bf1-a539-6f81537fe3ab', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', 'Друге місце', 'Усі короткі слова збираються після першого слова чи першої групи: Jučer sam mu poslala e-mail. Moj šef mi je rekao… Якщо першим стоїть дієслово — після нього: Poslala sam mu e-mail. Типова помилка українців — ставити коротке слово перед дієсловом, як «я йому сказала»: «Ja mu sam rekla» — неправильно; правильно Ja sam mu rekla.', '1-е слово + li + bih / sam / ću + mi / mu + me / ga + se + je', '[{"hr": "Jučer sam mu poslala ponudu.", "ua": "Учора я надіслала йому пропозицію."}, {"hr": "Šef mi je odobrio godišnji.", "ua": "Шеф погодив мені відпустку."}, {"hr": "Ja sam mu to već rekla.", "ua": "Я йому це вже сказала."}, {"hr": "Poslat ću Vam ugovor danas.", "ua": "Я надішлю вам договір сьогодні."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('34df6b52-4041-59da-ad72-cb3bcc255c03', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', 'Порядок: sam / ću — mi — ga — se — je', 'Якщо коротких слів кілька, порядок такий: li → дієслово-допоміжне (sam, si, smo, ste, su, ću, bih) → давальний (mi, ti, mu) → знахідний (me, te, ga) → se → je. Dao sam mu ga (я дав йому це). Javit ću ti se (я тобі озвуся). Je стоїть останнім: Dao mu ga je.', 'Dao sam mu ga. · Javit ću ti se. · Dao mu ga je.', '[{"hr": "Javit ću Vam se sutra.", "ua": "Я озвуся до вас завтра."}, {"hr": "Ugovor? Poslala sam ti ga jučer.", "ua": "Договір? Я надіслала тобі його вчора."}, {"hr": "Kolega mi ga je dao.", "ua": "Колега дав мені його."}, {"hr": "Bih li Vas mogla nešto pitati?", "ua": "Чи могла б я вас дещо запитати?"}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('9ed6b8b0-6506-595c-acc6-0f6ba46a20dd', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', 'Li у питаннях', 'Li стоїть після першого слова (найчастіше дієслова) і перед іншими короткими словами: Jesi li mu rekao? Možeš li mi pomoći? Hoćete li mi poslati račun? Je li ti šef odgovorio? Типова помилка — «Li možeš…» або «Možeš mi li…».', 'Možeš li mi…? · Jesi li mu…? · Je li ti…?', '[{"hr": "Možeš li mi poslati prezentaciju?", "ua": "Можеш надіслати мені презентацію?"}, {"hr": "Jeste li mu javili za sastanak?", "ua": "Ви повідомили йому про нараду?"}, {"hr": "Je li ti platio?", "ua": "Він тобі заплатив?"}, {"hr": "Hoćete li nam potvrditi termin?", "ua": "Ви підтвердите нам дату?"}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('12a1a49d-9117-5e9d-a64e-66be7a371810', 'A2', 'Відносний займенник koji', 'Odnosna zamjenica koji', 'Koji, koja, koje — «який, котрий» у підрядних реченнях: рід і число — як в іменника, відмінок — за роллю в підрядній частині (film koji sam gledao, žena kojoj sam pomogao); što у розмові; кома.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('b4720b9e-99e5-5b23-9b86-2cc9996f1f53', '12a1a49d-9117-5e9d-a64e-66be7a371810', 'Koji, koja, koje', 'Koji вводить речення, що описує іменник: Film koji sam gledala je odličan. Рід і число — як в іменника: knjiga koja…, dijete koje…, ljudi koji… Відмінок — за роллю в підрядному реченні: Knjiga koju čitam (знахідний — читаю що?). Перед koji — кома (якщо речення не на початку).', 'film koji… · serija koja… · dijete koje… · knjigu koju…', '[{"hr": "To je knjiga koju ti preporučujem.", "ua": "Це книжка, яку я тобі раджу."}, {"hr": "Gledali smo film koji je dobio nagradu.", "ua": "Ми дивилися фільм, який отримав нагороду."}, {"hr": "Znaš li ženu koja vodi emisiju?", "ua": "Ти знаєш жінку, яка веде передачу?"}, {"hr": "Ljudi koji žive ovdje su ljubazni.", "ua": "Люди, які тут живуть, привітні."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('0b19458e-d5e7-5803-b09f-ffaacccf9d29', '12a1a49d-9117-5e9d-a64e-66be7a371810', 'Відмінки koji', 'Koji відмінюється як прикметник: kojeg / kojega (Г, З для істот), kojem / kojemu (Д, М), kojim (О). Čovjek kojem sam pomogao. Grad u kojem živim. Prijatelj s kojim radim. Українською: «місто, в якому я живу» — так само.', 'u kojem · s kojim · kojem · kojeg · o kojoj', '[{"hr": "Grad u kojem živim je malen.", "ua": "Місто, в якому я живу, маленьке."}, {"hr": "To je kolega s kojim radim.", "ua": "Це колега, з яким я працюю."}, {"hr": "Članak o kojem pričam je na portalu.", "ua": "Стаття, про яку я розповідаю, на порталі."}, {"hr": "Susjed kojem smo pomogli zahvalio nam je.", "ua": "Сусід, якому ми допомогли, подякував нам."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('8e62902c-c4d4-5045-b203-b819a4c51f03', '12a1a49d-9117-5e9d-a64e-66be7a371810', 'Što замість koji у розмові', 'У розмовній мові іноді кажуть što замість koji в називному й знахідному: Film što smo gledali… На письмі й у навчанні краще koji. Ne miješajte: što у «Drago mi je što si došao» — це сполучник, а не відносний займенник.', 'Film koji smo gledali (книжно) — film što smo gledali (розмовно)', '[{"hr": "Jesi li pročitala poruku koju sam ti poslala?", "ua": "Ти прочитала повідомлення, яке я тобі надіслала?"}, {"hr": "Serija koju gledam ima tri sezone.", "ua": "Серіал, який я дивлюся, має три сезони."}, {"hr": "Pjesma koju sviraju je stara.", "ua": "Пісня, яку грають, стара."}, {"hr": "Restoran koji si preporučio je zatvoren.", "ua": "Ресторан, який ти порадив, зачинений."}]'::jsonb, 3)
on conflict (id) do nothing;
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'grammar_topic', '12a1a49d-9117-5e9d-a64e-66be7a371810', null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.'
where not exists (select 1 from public.content_reviews where entity_id = '12a1a49d-9117-5e9d-a64e-66be7a371810' and notes = 'Бета: тема граматики A2 за програмою A2 v2 (рішення власника 2026-11-12). Потрібна перевірка носієм.');
insert into public.grammar_topics (id, cefr, title_ua, title_hr, description, status)
values ('20fd9d75-7bef-51c3-9711-f09462b61b82', 'A2', 'Futur II — лише впізнавати', 'Futur II. — prepoznavanje', 'Futur II (budem, budeš, bude + -o / -la) у підрядних реченнях після kad, ako, čim, dok про майбутнє: Kad budem imao vremena… Вживати не обов’язково — на A2 досить впізнавати; замість нього — теперішній час доконаного дієслова.', 'PUBLISHED')
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('b2290b45-032d-5197-9ff9-3b2fcb380769', '20fd9d75-7bef-51c3-9711-f09462b61b82', 'Що таке futur II', 'Futur II = budem, budeš, bude, budemo, budete, budu + форма на -o / -la: budem imao, bude došla. Він уживається лише в підрядному реченні після kad, ako, čim, dok, prije nego što, коли йдеться про майбутнє: Kad budem imao vremena, nazvat ću te. Головне речення — futur I.', 'Kad budem imao…, nazvat ću… · Ako bude padala kiša, …', '[{"hr": "Kad budem imala vremena, nazvat ću te.", "ua": "Коли матиму час, подзвоню тобі."}, {"hr": "Ako bude lijepo vrijeme, idemo na izlet.", "ua": "Якщо буде гарна погода, поїдемо на екскурсію."}, {"hr": "Čim budemo znali datum, javit ćemo vam.", "ua": "Щойно знатимемо дату, повідомимо вам."}, {"hr": "Kad bude gotovo, reci mi.", "ua": "Коли буде готово, скажи мені."}]'::jsonb, 1)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('01a116e9-d182-5064-be94-70e74dc0307b', '20fd9d75-7bef-51c3-9711-f09462b61b82', 'Як сказати простіше', 'Замість futur II можна сказати теперішній час доконаного дієслова: Kad završim posao, nazvat ću te = Kad budem završio posao… Ako dođeš ranije, … = Ako budeš došao ranije… Для A2 цього досить. Типова помилка — «Kad ću imati vremena…»: після kad / ako про майбутнє ću не ставимо.', 'Kad završim… = Kad budem završio… · Ako dođeš… = Ako budeš došao…', '[{"hr": "Kad završim tečaj, tražit ću posao.", "ua": "Коли закінчу курс, шукатиму роботу."}, {"hr": "Ako dobijem vizu, putujem u ljeto.", "ua": "Якщо отримаю візу, улітку поїду."}, {"hr": "Čim stignem kući, poslat ću ti slike.", "ua": "Щойно приїду додому, надішлю тобі фото."}, {"hr": "Kad se vratiš, idemo na večeru.", "ua": "Коли повернешся, підемо на вечерю."}]'::jsonb, 2)
on conflict (id) do nothing;
insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
values ('a9a8fe0c-cae2-5dca-9ded-a16f512862e7', '20fd9d75-7bef-51c3-9711-f09462b61b82', 'Budem у сталих виразах', 'Budem трапляється й поза futur II: Ne znam hoću li moći, ako budem mogla, doći ću. Kako bude (як буде), Što bude, bit će (що буде, те буде). Bude li… — «якщо буде»: Bude li problema, zovite. Такі вирази варто впізнавати на слух.', 'kako bude · što bude, bit će · bude li…', '[{"hr": "Vidjet ćemo kako bude.", "ua": "Побачимо, як буде."}, {"hr": "Što bude, bit će.", "ua": "Що буде, те буде."}, {"hr": "Bude li problema, nazovite nas.", "ua": "Якщо будуть проблеми, телефонуйте нам."}, {"hr": "Ako budem mogla, doći ću.", "ua": "Якщо зможу, прийду."}]'::jsonb, 3)
on conflict (id) do nothing;
