-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_mod int; v_units int; v_topics int; v_rules int; v_read int;
begin
  select count(*) into v_mod from (values ('2cfdcacf-767e-5f3f-bb15-9b245bd598c9'::uuid, 1), ('0b2b8e34-d7e7-5200-a5ee-584af028ed75'::uuid, 2), ('38b2ee69-f7d3-5de2-8208-b1fa31501558'::uuid, 3), ('8fad33b4-f461-5119-b5e5-f94b700e283c'::uuid, 4), ('aa10630b-c7e4-5d3a-b3dc-739e9eea9e06'::uuid, 5), ('f811eff6-8d8a-5fac-8ae7-6b78020976f1'::uuid, 6), ('d66361ac-89bc-5021-99ad-c3f61c71145c'::uuid, 7), ('f72289b9-a174-5dd1-8cf6-553684bd120d'::uuid, 8), ('a198575a-bafc-51b5-b325-95aa7d6c9d8a'::uuid, 9), ('285d2a27-68a4-5302-afc3-9595d071647a'::uuid, 10), ('81b58843-3837-5c58-ab5d-4d16e30620b2'::uuid, 11), ('5b885d2c-55ee-5635-91be-a4746da43999'::uuid, 12), ('47c98d89-5811-5425-af88-26e8249d361b'::uuid, 13), ('a22f1345-0879-5cde-ad47-4a76556dcf7e'::uuid, 14)) as t(id, o) join public.modules md on md.id = t.id and md.order_index = t.o and md.level_code = 'A2';
  select count(*) into v_units from public.units u join public.modules md on md.id = u.module_id where md.level_code = 'A2';
  select count(*) into v_topics from public.grammar_topics where id in ('0c68352a-803a-5410-a59b-91f2c1ddc49f', '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc', '0b2de584-05a6-5570-a129-366fcb94766d', '2d4021eb-fd3e-5388-a44b-3f541c5990f8', '926638d7-1396-512e-8a05-065c4464b85a', 'b7103d09-8e69-53f7-8f17-a90c771fa1a2', 'feaaa674-66e6-5521-ba6e-b5d1507cd351', '4101ee05-3efe-5a98-a9e5-f0f327436268', 'd777c847-266e-57ef-a5a2-f417f12f1b3e', '78491f05-4871-51e6-aa8e-7f81fe2f6099', '17b75bc6-fca0-5f09-830c-ab7f37279022', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', '879e6305-0f75-5e88-abff-e27819f2d92d', 'b5076495-20a1-53e5-be78-eee365980865', '6da44157-69d7-5261-8289-fe910fd60f59', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', '9c01b59a-6b4f-52a9-abfd-d78278072098', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', '12a1a49d-9117-5e9d-a64e-66be7a371810', '20fd9d75-7bef-51c3-9711-f09462b61b82') and status = 'PUBLISHED' and cefr = 'A2';
  select count(*) into v_rules from public.grammar_rules where topic_id in ('0c68352a-803a-5410-a59b-91f2c1ddc49f', '59c6c708-59b5-5781-bf5d-4ecd5aa8b7dc', '0b2de584-05a6-5570-a129-366fcb94766d', '2d4021eb-fd3e-5388-a44b-3f541c5990f8', '926638d7-1396-512e-8a05-065c4464b85a', 'b7103d09-8e69-53f7-8f17-a90c771fa1a2', 'feaaa674-66e6-5521-ba6e-b5d1507cd351', '4101ee05-3efe-5a98-a9e5-f0f327436268', 'd777c847-266e-57ef-a5a2-f417f12f1b3e', '78491f05-4871-51e6-aa8e-7f81fe2f6099', '17b75bc6-fca0-5f09-830c-ab7f37279022', '6de8bf6e-97a1-5cb3-8e31-538b07c36309', '879e6305-0f75-5e88-abff-e27819f2d92d', 'b5076495-20a1-53e5-be78-eee365980865', '6da44157-69d7-5261-8289-fe910fd60f59', 'd1e0a0ca-707a-5b16-bcdf-06037cb17e0e', '3a13fbe7-c0e4-55f8-b938-5579165e11bf', '9c01b59a-6b4f-52a9-abfd-d78278072098', 'a6dba6b3-0b0a-588c-acd4-7eedced88519', 'ec75057c-1f8d-51e1-9946-1ff5bbfeebca', '12a1a49d-9117-5e9d-a64e-66be7a371810', '20fd9d75-7bef-51c3-9711-f09462b61b82');
  select count(*) into v_read from public.reading_texts where cefr = 'A2' and module_order not between 1 and 14;
  if v_mod <> 14 then raise exception 'A2: на своїх місцях % модулів з 14', v_mod; end if;
  if v_units <> 14 then raise exception 'A2: юнітів %, очікувалось 14', v_units; end if;
  if v_topics <> 22 then raise exception 'A2: опублікованих тем граматики % з 22', v_topics; end if;
  if v_rules < 67 then raise exception 'A2: правил граматики % (очікувалось 67)', v_rules; end if;
  if v_read > 0 then raise exception 'A2: % текстів без модуля', v_read; end if;
  raise notice 'Готово: програма A2 v2 — 14 модулів, 22 тем граматики, правил %', v_rules;
end $$;

